package com.vandorlabs.neoforge.segmented;

import net.minecraft.core.*;
import net.minecraft.world.level.*;
import net.minecraft.world.entity.MoverType;
import net.minecraft.world.entity.decoration.ArmorStand;
import net.minecraft.world.phys.*;

/** Dedicated/client collision focus, independent of documentation cameras and editor matrices. */
public final class SegmentedCollisionChecks {
 public static final BlockPos ROOT=new BlockPos(15,160,15);
 private static net.minecraft.world.level.block.Block block(){return net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(SegmentedWorldClientFixture.ID);}
 private static void need(boolean value,String why){if(!value)throw new AssertionError("Native Segmented collision: "+why);}
 static NativeSegmentedDoorEntity create(Level level,int height){for(int row=0;row<height;row++){var at=ROOT.below(row);level.setBlock(at,block().defaultBlockState(),2);var tile=(NativeSegmentedDoorEntity)level.getBlockEntity(at);tile.topOffset=row;tile.height=height;tile.column=0;tile.columns=1;tile.formed=true;tile.configured=true;tile.from=1;tile.targetOpen=true;tile.settings=NativeSegmentedDoorSettings.DEFAULT;tile.duration=1;tile.started=level.getGameTime();tile.publishLocal();NativeSegmentedTargets.add(tile);}return (NativeSegmentedDoorEntity)level.getBlockEntity(ROOT);}
 static void probe(Level level,NativeSegmentedDoorEntity root,int row){var cfg=root.settings();int count=cfg.treadPixels<16&&!cfg.straight?16/cfg.treadPixels:1,strip=count/2,rotation=switch(root.facing()){case NORTH->0;case WEST->1;case SOUTH->2;case EAST->3;default->0;};var at=root.getBlockPos();var t=count==1?com.vandorlabs.segmented.SegmentedHitGeometry.transform(at.getX(),at.getY(),at.getZ(),rotation,row,root.height(),root.column(),root.columnsCount(),root.pose(0),cfg.direction,cfg.straight,cfg.depthOffset()):com.vandorlabs.segmented.SegmentedHitGeometry.treadTransform(at.getX(),at.getY(),at.getZ(),rotation,row,root.height(),root.column(),root.columnsCount(),root.pose(0),cfg.direction,cfg.treadPixels,cfg.depthOffset(),strip);double center=(strip+.5)/count;double[] point=t.point(cfg.direction<2?.5:center,cfg.direction<2?center-.5:0,0);var query=new AABB(point[0]-.05,point[1]-.05,point[2]-.05,point[0]+.05,point[1]+.05,point[2]+.05);boolean found=false;for(var shape:level.getBlockCollisions(null,query))for(var box:shape.toAabbs())if(box.intersects(query))found=true;need(found,"body absent from actual World collision query");
  var actor=new ArmorStand(level,point[0],point[1],point[2]);int axis=Math.abs(t.r[5])>Math.abs(t.r[2])?1:0;if(Math.abs(t.r[8])>Math.abs(t.r[axis*3+2]))axis=2;double[] start={point[0],point[1]-actor.getBbHeight()/2D,point[2]},move={0,0,0};start[axis]-=3;move[axis]=6;actor.setPos(start[0],start[1],start[2]);actor.move(MoverType.SELF,new Vec3(move[0],move[1],move[2]));double result=axis==0?actor.getX():axis==1?actor.getY():actor.getZ();need(result<start[axis]+5.9,"entity moved through a solid panel");actor.discard();
 }
 static void matrix(net.minecraft.server.level.ServerLevel level){int checks=0;for(int height:new int[]{1,4,32}){var root=create(level,height);for(var facing:Direction.Plane.HORIZONTAL){for(int row=0;row<height;row++)level.setBlock(ROOT.below(row),block().defaultBlockState().setValue(NativeSegmentedDoorBlock.FACING,facing),0);for(int direction=0;direction<4;direction++)for(boolean straight:new boolean[]{false,true})for(int pixels:new int[]{1,2,4,8,16})for(int position=0;position<3;position++){var cfg=new NativeSegmentedDoorSettings(direction,straight,1,0,false,0,false,NativeSegmentedDoorSettings.DEFAULT.glass,position,pixels);for(int row=0;row<height;row++){var tile=(NativeSegmentedDoorEntity)level.getBlockEntity(ROOT.below(row));tile.settings=cfg;tile.from=1;tile.targetOpen=true;tile.publishLocal();}for(int row:new java.util.TreeSet<Integer>(java.util.Arrays.asList(0,height-1))){probe(level,root,row);checks++;}}}for(int row=0;row<height;row++)level.removeBlock(ROOT.below(row),false);}create(level,4);for(int row=0;row<4;row++)level.sendBlockUpdated(ROOT.below(row),level.getBlockState(ROOT.below(row)),level.getBlockState(ROOT.below(row)),3);System.out.println("[vandorlabs][segmented-world-client] collision-matrix PASS cases="+checks+" all facings directions modes treads depths heights1/4/32");}
 private SegmentedCollisionChecks(){}
}
